WITH base AS (SELECT id, order_id, amount, paid_at, LOWER(status) status_lower, HOUR(paid_at) paid_at_hour FROM payments WHERE paid_at > DATE '2023-10-22' AND method IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM base), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT DATE_TRUNC('QUARTER', paid_at) AS quarter_start, ROUND(AVG(amount), 2) AS avg_amount, SUM(amount) AS total_amount, APPROX_PERCENTILE(session_no, 0.5) AS session_no_p50, MIN(paid_at) AS first_seen FROM islands GROUP BY quarter_start HAVING avg_amount >= 0
